const fs = require('fs');

const SOURCE_FILE = 'test-data/adcell-products.csv';
const OUTPUT_FILE = 'products.json';
const SOURCE_PREFIX = 'adcell-';

function parseCsvLine(line) {
  const values = [];
    let value = '';
      let inQuotes = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];

                if (char === '"') {
                      if (inQuotes && line[i + 1] === '"') {
                              value += '"';
                                      i++;
                                            } else {
                                                    inQuotes = !inQuotes;
                                                          }
                                                              } else if (char === ';' && !inQuotes) {
                                                                    values.push(value);
                                                                          value = '';
                                                                              } else {
                                                                                    value += char;
                                                                                        }
                                                                                          }

                                                                                            values.push(value);
                                                                                              return values;
                                                                                              }

                                                                                              function parseCsv(content) {
                                                                                                const lines = content
                                                                                                    .replace(/^\uFEFF/, '')
                                                                                                        .split(/\r?\n/)
                                                                                                            .filter(line => line.trim() !== '');

                                                                                                              if (lines.length < 2) {
                                                                                                                  throw new Error('ADCELL-Testdatei enthält keine Produktdaten.');
                                                                                                                    }

                                                                                                                      const headers = parseCsvLine(lines[0]).map(header =>
                                                                                                                          header.trim().toLowerCase()
                                                                                                                            );

                                                                                                                              return lines.slice(1).map(line => {
                                                                                                                                  const values = parseCsvLine(line);
                                                                                                                                      const row = {};

                                                                                                                                          headers.forEach((header, index) => {
                                                                                                                                                row[header] = values[index] ?? '';
                                                                                                                                                    });

                                                                                                                                                        return row;
                                                                                                                                                          });
                                                                                                                                                          }

                                                                                                                                                          function getField(row, names) {
                                                                                                                                                            for (const name of names) {
                                                                                                                                                                const value = row[name.toLowerCase()];

                                                                                                                                                                    if (value !== undefined && String(value).trim() !== '') {
                                                                                                                                                                          return String(value).trim();
                                                                                                                                                                              }
                                                                                                                                                                                }

                                                                                                                                                                                  return '';
                                                                                                                                                                                  }

                                                                                                                                                                                  function parsePrice(value) {
                                                                                                                                                                                    if (!value) {
                                                                                                                                                                                        return 0;
                                                                                                                                                                                          }

                                                                                                                                                                                            let normalized = String(value)
                                                                                                                                                                                                .trim()
                                                                                                                                                                                                    .replace(/[€\s]/g, '');

                                                                                                                                                                                                      if (normalized.includes(',') && normalized.includes('.')) {
                                                                                                                                                                                                          normalized = normalized.replace(/\./g, '').replace(',', '.');
                                                                                                                                                                                                            } else if (normalized.includes(',')) {
                                                                                                                                                                                                                normalized = normalized.replace(',', '.');
                                                                                                                                                                                                                  }

                                                                                                                                                                                                                    const price = Number(normalized);

                                                                                                                                                                                                                      return Number.isFinite(price) ? price : 0;
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                      function createProductId(row, index) {
                                                                                                                                                                                                                        const articleNumber = getField(row, [
                                                                                                                                                                                                                            'ean',
                                                                                                                                                                                                                                'aan',
                                                                                                                                                                                                                                    'anbieter artikelnummer',
                                                                                                                                                                                                                                        'anbieter-artikelnummer',
                                                                                                                                                                                                                                            'han',
                                                                                                                                                                                                                                                'herstellerartikelnummer',
                                                                                                                                                                                                                                                    'hersteller-artikelnummer'
                                                                                                                                                                                                                                                      ]);

                                                                                                                                                                                                                                                        if (articleNumber) {
                                                                                                                                                                                                                                                            return `${SOURCE_PREFIX}${articleNumber}`;
                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                return `${SOURCE_PREFIX}test-${index + 1}`;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                function importAdcellProducts() {
                                                                                                                                                                                                                                                                  console.log('Broki ADCELL-Import gestartet.');

                                                                                                                                                                                                                                                                    if (!fs.existsSync(SOURCE_FILE)) {
                                                                                                                                                                                                                                                                        throw new Error(
                                                                                                                                                                                                                                                                              `ADCELL-Testdatei nicht gefunden: ${SOURCE_FILE}`
                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                      const csvContent = fs.readFileSync(SOURCE_FILE, 'utf8');
                                                                                                                                                                                                                                                                                        const rows = parseCsv(csvContent);

                                                                                                                                                                                                                                                                                          let existingProducts = [];

                                                                                                                                                                                                                                                                                            if (fs.existsSync(OUTPUT_FILE)) {
                                                                                                                                                                                                                                                                                                const existingData = fs.readFileSync(OUTPUT_FILE, 'utf8');
                                                                                                                                                                                                                                                                                                    existingProducts = JSON.parse(existingData);

                                                                                                                                                                                                                                                                                                        if (!Array.isArray(existingProducts)) {
                                                                                                                                                                                                                                                                                                              throw new Error(
                                                                                                                                                                                                                                                                                                                      'products.json enthält keine gültige Produktliste.'
                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                    const today = new Date().toISOString().split('T')[0];

                                                                                                                                                                                                                                                                                                                                      const importedProducts = rows.map((row, index) => ({
                                                                                                                                                                                                                                                                                                                                          id: createProductId(row, index),

                                                                                                                                                                                                                                                                                                                                              name: getField(row, [
                                                                                                                                                                                                                                                                                                                                                    'produkt-titel',
                                                                                                                                                                                                                                                                                                                                                          'produkt titel',
                                                                                                                                                                                                                                                                                                                                                                'produkttitel',
                                                                                                                                                                                                                                                                                                                                                                      'titel',
                                                                                                                                                                                                                                                                                                                                                                            'title'
                                                                                                                                                                                                                                                                                                                                                                                ]) || 'Unbenanntes Produkt',

                                                                                                                                                                                                                                                                                                                                                                                    category: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                          'produktkategorie',
                                                                                                                                                                                                                                                                                                                                                                                                'produkt-kategorie',
                                                                                                                                                                                                                                                                                                                                                                                                      'kategorie',
                                                                                                                                                                                                                                                                                                                                                                                                            'category'
                                                                                                                                                                                                                                                                                                                                                                                                                ]) || 'Sonstiges',

                                                                                                                                                                                                                                                                                                                                                                                                                    brand: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                          'hersteller',
                                                                                                                                                                                                                                                                                                                                                                                                                                'manufacturer',
                                                                                                                                                                                                                                                                                                                                                                                                                                      'brand'
                                                                                                                                                                                                                                                                                                                                                                                                                                          ]),

                                                                                                                                                                                                                                                                                                                                                                                                                                              description: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                    'produktbeschreibung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                          'produktbeschreibung (lang)',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                'beschreibung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'description'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              image: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'produktbild-url',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'produktbild url',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'bild-url',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'image'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              merchant: 'ADCELL Testquelle',

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  price: parsePrice(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'bruttopreis',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'brutto-preis',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'preis',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'price'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      currency: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'währung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'waehrung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'currency'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]) || 'EUR',

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                originalPrice: (() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const value = getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'streichpreis',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'originalpreis',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'original-price'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return value ? parsePrice(value) : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })(),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  affiliateUrl: getField(row, [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'produkt-deeplink',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'produkt deeplink',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'deeplink'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ]),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            active: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                lastUpdated: today
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const importedIds = new Set(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        importedProducts.map(product => String(product.id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const existingAdcellProducts = existingProducts.filter(product =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String(product.id || '').startsWith(SOURCE_PREFIX)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const existingAdcellIds = new Set(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        existingAdcellProducts.map(product => String(product.id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const newProducts = importedProducts.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                product => !existingAdcellIds.has(String(product.id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const updatedProducts = importedProducts.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        product => existingAdcellIds.has(String(product.id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const deactivatedProducts = existingAdcellProducts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .filter(product => !importedIds.has(String(product.id)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .map(product => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ...product,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                active: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      lastUpdated: today
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const otherProducts = existingProducts.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                product => !String(product.id || '').startsWith(SOURCE_PREFIX)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const finalProducts = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ...otherProducts,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ...importedProducts,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ...deactivatedProducts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fs.writeFileSync(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        OUTPUT_FILE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            JSON.stringify(finalProducts, null, 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'utf8'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log('Broki ADCELL-Import erfolgreich.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(`Quelle: ${SOURCE_FILE}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log(`Von ADCELL-Testfeed geladen: ${importedProducts.length}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log(`Neue Produkte: ${newProducts.length}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log(`Aktualisierte Produkte: ${updatedProducts.length}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  `Deaktivierte ADCELL-Produkte: ${deactivatedProducts.length}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `Produkte insgesamt in products.json: ${finalProducts.length}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              importAdcellProducts();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.error('Broki ADCELL-Import fehlgeschlagen.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.error(error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
